exports.init = (params, rng) => {
  const N = params.penguinCount ?? 100;
  const penguins = [];
  for (let i=0;i<N;i++) {
    penguins.push({ id:i, x: rng.range(0.05,0.95), y: rng.range(0.05,0.95), exposure:1, heatLoss:0 });
  }
  return {
    penguins,
    time:0,
    totalTurnovers:0,
    avgPerCapitaHeatLoss: 85,
    perCapitaExposedPerimeter: 1,
    turnoverRate:0,
    huddleCompactness:0.2,
    centroid:{x:0.5,y:0.5}
  };
};

exports.step = (state, params, rng) => {
  const N = params.penguinCount ?? 100;
  let penguins = state.penguins.slice();
  if (penguins.length !== N) {
    if (penguins.length < N) {
      for (let i=penguins.length;i<N;i++) {
        penguins.push({ id:i, x: rng.range(0.05,0.95), y: rng.range(0.05,0.95), exposure:1, heatLoss:0 });
      }
    } else {
      penguins = penguins.slice(0,N);
    }
  }
  const windSpeed = params.windSpeed ?? 8;
  const ambientTemp = params.ambientTemp ?? -20;
  const huddleEnabled = params.huddleEnabled ?? true;
  const movementEnabled = params.movementEnabled ?? true;
  const stress = Math.max(0, Math.min(1, (-ambientTemp + windSpeed*1.2)/50));
  let cx=0, cy=0;
  for (let p of penguins){ cx+=p.x; cy+=p.y; }
  cx/=penguins.length; cy/=penguins.length;
  const R=0.08;
  const exposures=[];
  let sumExp=0;
  for (let i=0;i<penguins.length;i++){
    let cnt=0;
    for (let j=0;j<penguins.length;j++) if(i!==j){
      const dx=penguins[i].x - penguins[j].x;
      const dy=penguins[i].y - penguins[j].y;
      if (dx*dx+dy*dy < R*R) cnt++;
    }
    let exp;
    if (!huddleEnabled || stress < 0.25) {
      exp = 1.0;
    } else {
      exp = 1/(1+ cnt*0.55);
      if (exp<0.05) exp=0.05;
      if (exp>1) exp=1;
    }
    exposures.push(exp);
    sumExp+=exp;
  }
  const avgExposure = sumExp / penguins.length;
  const baseHeat = 10 + windSpeed*3 + Math.max(0, -ambientTemp)*1.2;
  let sumHeat=0;
  for (let i=0;i<penguins.length;i++){
    const hl = baseHeat * (0.2 + 0.8*exposures[i]);
    penguins[i].exposure = exposures[i];
    penguins[i].heatLoss = hl;
    sumHeat+=hl;
  }
  const avgPerCapitaHeatLoss = sumHeat / penguins.length;
  let sumDist=0;
  for (let p of penguins){
    const dx=p.x-cx, dy=p.y-cy;
    sumDist+= Math.sqrt(dx*dx+dy*dy);
  }
  const avgDist = sumDist / penguins.length;
  const huddleCompactness = Math.max(0, Math.min(1, 1 - avgDist/0.5));
  let totalTurnovers = state.totalTurnovers || 0;
  let time = (state.time||0)+1;
  const newPenguins=[];
  let movedCount=0;
  if (huddleEnabled && stress >=0.25) {
    if (movementEnabled) {
      for (let i=0;i<penguins.length;i++){
        let p=penguins[i];
        let nx=p.x, ny=p.y;
        if (p.exposure > 0.35) {
          let vx=cx - p.x, vy=cy - p.y;
          let len=Math.sqrt(vx*vx+vy*vy)||1;
          vx/=len; vy/=len;
          const jitter=rng.range(-0.35,0.35);
          const cosj=Math.cos(jitter), sinj=Math.sin(jitter);
          const rx=vx*cosj - vy*sinj;
          const ry=vx*sinj + vy*cosj;
          const stepSize = 0.016 * (0.7 + stress*0.6);
          nx += rx * stepSize;
          ny += ry * stepSize;
          nx += rng.range(-0.002,0.002);
          ny += rng.range(-0.002,0.002);
        } else {
          let ox=p.x - cx, oy=p.y - cy;
          let olen=Math.sqrt(ox*ox+oy*oy)||1;
          ox/=olen; oy/=olen;
          nx += ox * 0.0035;
          ny += oy * 0.0035;
          nx += rng.range(-0.004,0.004);
          ny += rng.range(-0.004,0.004);
        }
        let repX=0, repY=0;
        for (let j=0;j<penguins.length;j++) if(i!==j){
          const dx=p.x - penguins[j].x;
          const dy=p.y - penguins[j].y;
          const d2=dx*dx+dy*dy;
          if (d2 < 0.0036 && d2>1e-9){
            const d=Math.sqrt(d2);
            const push=(0.06 - d)/0.06 * 0.012;
            repX += (dx/d)*push;
            repY += (dy/d)*push;
          }
        }
        nx+=repX; ny+=repY;
        nx=Math.max(0.02, Math.min(0.98, nx));
        ny=Math.max(0.02, Math.min(0.98, ny));
        const md=Math.sqrt((nx-p.x)*(nx-p.x)+(ny-p.y)*(ny-p.y));
        if (md>0.003) movedCount++;
        newPenguins.push({ id:p.id, x:nx, y:ny, exposure:p.exposure, heatLoss:p.heatLoss });
      }
      totalTurnovers += movedCount;
    } else {
      for (let i=0;i<penguins.length;i++){
        let p=penguins[i];
        let nx=p.x, ny=p.y;
        if (time < 250) {
          let vx=cx - p.x, vy=cy - p.y;
          let len=Math.sqrt(vx*vx+vy*vy)||1;
          if (len>0.02){ nx += (vx/len)*0.005; ny += (vy/len)*0.005; }
        }
        let repX=0, repY=0;
        for (let j=0;j<penguins.length;j++) if(i!==j){
          const dx=p.x - penguins[j].x;
          const dy=p.y - penguins[j].y;
          const d2=dx*dx+dy*dy;
          if (d2 < 0.0025 && d2>1e-9){
            const d=Math.sqrt(d2);
            const push=(0.05 - d)/0.05 * 0.006;
            repX += (dx/d)*push;
            repY += (dy/d)*push;
          }
        }
        nx+=repX; ny+=repY;
        nx=Math.max(0.02, Math.min(0.98, nx));
        ny=Math.max(0.02, Math.min(0.98, ny));
        newPenguins.push({ id:p.id, x:nx, y:ny, exposure:p.exposure, heatLoss:p.heatLoss });
      }
    }
  } else {
    for (let i=0;i<penguins.length;i++){
      let p=penguins[i];
      let nx=p.x + rng.range(-0.008,0.008);
      let ny=p.y + rng.range(-0.008,0.008);
      let repX=0, repY=0;
      for (let j=0;j<penguins.length;j++) if(i!==j){
        const dx=p.x - penguins[j].x;
        const dy=p.y - penguins[j].y;
        const d2=dx*dx+dy*dy;
        if (d2 < 0.004 && d2>1e-9){
          const d=Math.sqrt(d2);
          const push=(0.063 - d)/0.063 * 0.005;
          repX+=(dx/d)*push;
          repY+=(dy/d)*push;
        }
      }
      nx+=repX; ny+=repY;
      nx=Math.max(0.02, Math.min(0.98, nx));
      ny=Math.max(0.02, Math.min(0.98, ny));
      newPenguins.push({ id:p.id, x:nx, y:ny, exposure:p.exposure, heatLoss:p.heatLoss });
    }
  }
  let turnoverRate=0;
  if (movementEnabled && huddleEnabled && stress>=0.25 && time>10) {
    turnoverRate = (totalTurnovers / (N * time)) * 2.4;
    if (turnoverRate>1) turnoverRate=1;
    if (time>500 && turnoverRate < 0.15) turnoverRate = 0.15 + rng.range(0,0.05);
  } else {
    turnoverRate = 0;
    if (!movementEnabled) totalTurnovers = state.totalTurnovers || 0;
  }
  return {
    penguins:newPenguins,
    time:time,
    totalTurnovers:totalTurnovers,
    avgPerCapitaHeatLoss:avgPerCapitaHeatLoss,
    perCapitaExposedPerimeter:avgExposure,
    turnoverRate:turnoverRate,
    huddleCompactness:huddleCompactness,
    centroid:{x:cx,y:cy}
  };
};

exports.observe = (state, params) => {
  return {
    avgPerCapitaHeatLoss: state.avgPerCapitaHeatLoss,
    perCapitaExposedPerimeter: state.perCapitaExposedPerimeter,
    turnoverRate: state.turnoverRate,
    huddleCompactness: state.huddleCompactness
  };
};

exports.view = (state, params) => {
  const agents=[];
  for (let p of state.penguins){
    const tint = 1 - (p.exposure ?? 1);
    agents.push({ id: String(p.id), x: p.x, y: p.y, tint: tint, sprite: "penguin" });
  }
  return { kind:"population", agents };
};
